import{t as e}from"./utils-COoNfFoj.js";var t={slug:`federico-donatone`,influencerName:`Federico Donatone`,influencerHandle:`@federicodonatone`,influencerAvatarUrl:`${e}/federico-donatone-avatar.png`,heroDescription:`The rationale is to eliminate fragmented outbound tools and replace them with one AI system that runs the entire process in one place. It lets you one-shot any cold email tool and replace it with a fully AI-driven outbound motion. It handles everything end-to-end: identifying target accounts from an AI-generated company description, finding the most relevant decision-makers, and building fully custom messaging. With this, you no longer need tools like Apollo.io.`,assetTitle:`growthcab OS`,screenshotUrl:`${e}/federico-donatone.png`,remixUrl:`https://www.perplexity.ai/computer/a/growth-cab-os-_mO9VBnJT0uvsTvHO_4jww`,promptTitle:`Try Federico's prompt`,promptText:`Design a one-shot alternative to Clay and Claygent—an AI-powered prospecting tool that outperforms both. It should let users discover companies via natural language, identify key contacts by filters, and run a waterfall pipeline that gathers deep, structured and unstructured insights on each prospect (company info, role context, and relevant signals). The system should then use this data to generate highly personalized outreach and either integrate with tools like Gemini, Prospeo, and Instantly or include a built-in sequencer—functioning as a complete end-to-end GTM engine.`};export{t as default};
